  if (atkOn) { const at = document.createElement("span"); at.className = "atk"; at.dataset.k = "atk"; at.textContent = info.atk; at.title = "攻撃判定"; mi.appendChild(at); }
  if (tagsOn) info.tags.forEach(t => { const tg = document.createElement("span"); tg.className = "tg tg-" + t.id; tg.dataset.k = t.id; tg.textContent = t.text || t.label; tg.title = t.text ? t.text + "：" + t.full : t.full; mi.appendChild(tg); });
