const THEME_KEY = "tekken-checksheet-theme";
const THEME_BG = { navy: "#1a1c2c", heat: "#15110e", gold: "#0d0d10", steel: "#0f141a", jade: "#0e1815", dojo: "#f3efe6" };
function applyTheme(t) {
  if (!THEME_BG[t]) t = "gold";
  document.documentElement.setAttribute("data-theme", t);
  const m = document.querySelector('meta[name="theme-color"]');
  if (m) m.setAttribute("content", THEME_BG[t]);
  const sel = document.getElementById("theme");
  if (sel) sel.value = t;
}
(function initTheme() {
  let t = "gold";
  try { t = localStorage.getItem(THEME_KEY) || "gold"; } catch (_) {}
  applyTheme(t);
  document.getElementById("theme").addEventListener("change", e => {
    applyTheme(e.target.value);
    try { localStorage.setItem(THEME_KEY, e.target.value); } catch (_) {}
  });
})();

